// Normaliza a coordenada para servir de chave (arredonda a 4 casas)
function normCoord(txt) {
  if (!txt) return "";
  const nums = String(txt).match(/-?\d+[.,]?\d*/g);
  if (nums && nums.length >= 2) {
    const a = parseFloat(nums[0].replace(",", "."));
    const b = parseFloat(nums[1].replace(",", "."));
    if (!isNaN(a) && !isNaN(b)) return a.toFixed(4) + "," + b.toFixed(4);
  }
  return String(txt).trim();
}
// Armazenamento persistente por coordenada (window.storage do ambiente de artefatos)
async function loadHist(key) {
  try { const r = await window.storage.get("pivo:" + key); return r ? JSON.parse(r.value) : []; }
  catch (e) { return []; }
}
async function saveHist(key, arr) {
  try { const r = await window.storage.set("pivo:" + key, JSON.stringify(arr)); return !!r; }
  catch (e) { return false; }
}

