const EX_CAD = { empresa: "Proojet Agro Consultoria", proprietario: "Fazenda Jalapão (exemplo)", fazenda: "Jalapão", cidade: "Mateiros", estado: "TO", coordenadas: "-10.5432, -46.4123", comp: "374", vazao: "351", vel: "250", raio: "400", espacamento: "5", pressao: "3.8", laminaProjeto: "6.5637", canhao: "Sim" };

/* ---------- MOTOR DE CÁLCULO ---------- */
function calcUnif(coletores) {
  const v = coletores.map((c) => {
    const vs = [num(c.v1), num(c.v2), num(c.v3), num(c.v4)].filter((x) => x != null);
    if (!vs.length) return null;
    const li = (vs.reduce((a, b) => a + b, 0) / vs.length / AREA) * 10;
    return { si: +c.si, dist: num(c.dist), li };
  }).filter(Boolean);
  if (!v.length) return null;
  const sSi = v.reduce((a, r) => a + r.si, 0);
  const lmp = v.reduce((a, r) => a + r.si * r.li, 0) / sSi;
  const cuc = (1 - v.reduce((a, r) => a + r.si * Math.abs(r.li - lmp), 0) / (lmp * sSi)) * 100;
  const ord = v.map((r) => r.li).sort((a, b) => a - b);
  const k = Math.max(1, Math.ceil(ord.length * 0.25));
  const lp25 = ord.slice(0, k).reduce((a, b) => a + b, 0) / k;
  return { v, lmp, cuc, ud: (lp25 / lmp) * 100, lp25, n: v.length };
}
function calcHidro(bicos, canhao) {
  const p = bicos.map((b, i) => {
    const t = num(b.tempo), vol = num(b.vol);
    return { pos: i + 1, pres: num(b.pres), diam: num(b.diam), vazao: t && vol != null ? (vol / t) * 3.6 : null };
  });
  const valid = p.filter((r) => r.vazao != null);
  if (!valid.length) return null;
  const media = valid.reduce((a, r) => a + r.vazao, 0) / valid.length;
  const temCanhao = canhao && valid.length >= 2;
  const canhaoBico = temCanhao ? valid[valid.length - 1] : null;
  const asp = temCanhao ? valid.slice(0, -1) : valid;
  const ord = [...asp].sort((a, b) => a.vazao - b.vazao);
  const novaPos = {};
  ord.forEach((r, i) => (novaPos[r.pos] = i + 1));
  if (canhaoBico) novaPos[canhaoBico.pos] = valid.length;
  const ajustado = ord.map((r, i) => ({ novaPos: i + 1, vazao: +r.vazao.toFixed(2) }));
  if (canhaoBico) ajustado.push({ novaPos: valid.length, vazao: +canhaoBico.vazao.toFixed(2), canhao: true });
  const mapping = valid.map((r) => ({ pos: r.pos, vazao: r.vazao, diam: r.diam, novaPos: novaPos[r.pos], delta: novaPos[r.pos] - r.pos, canhao: canhaoBico && r.pos === canhaoBico.pos }));
  return { valid, media, n: valid.length, ajustado, mapping, temCanhao };
}
function calcAdeq(unif, lproj) {
  if (!unif) return null;
  const val = unif.v.filter((c) => c.dist != null && c.dist > 0);
  if (val.length < 2) return null;
  const sW = val.reduce((a, c) => a + c.dist, 0);
  const ord = [...val].sort((a, b) => b.li - a.li);
  let acc = 0;
  const curva = ord.map((c) => { acc += c.dist; return { freq: +((acc / sW) * 100).toFixed(2), lamina: +c.li.toFixed(2) }; });
  const alvo = num(lproj);
  let adq = null;
  if (alvo != null) {
    let prev = { freq: 0, lamina: curva[0].lamina };
    adq = 100;
    for (const pt of curva) { if (pt.lamina <= alvo) { adq = prev.lamina === pt.lamina ? pt.freq : +(prev.freq + ((prev.lamina - alvo) / (prev.lamina - pt.lamina)) * (pt.freq - prev.freq)).toFixed(1); break; } prev = pt; }
  }
  return { curva, adq, lmp: unif.lmp };
}
function calcControle(cad) {
  const comp = num(cad.comp), vazao = num(cad.vazao), vel = num(cad.vel), raio = num(cad.raio);
  if (!comp || !vel || !vazao || !raio) return null;
  const tempo = (2 * Math.PI * comp) / vel;
  const lamina100 = (tempo * vazao) / (10 * ((Math.PI * raio * raio) / 10000));
  const tabela = [];
  for (let pp = 10; pp <= 100; pp++) tabela.push({ p: pp, vel: (pp / 100) * vel, tv: (tempo * 100) / pp, lam: (lamina100 * 100) / pp });
  return { tempo, lamina100, tabela };
}

const fCUC = (x) => (x >= 90 ? ["Excelente", C.primary] : x >= 80 ? ["Bom", C.up] : x >= 70 ? ["Razoável", C.soil] : ["Baixo", C.warn]);
const fUD = (x) => (x >= 84 ? ["Excelente", C.primary] : x >= 68 ? ["Bom", C.up] : x >= 56 ? ["Razoável", C.soil] : ["Baixo", C.warn]);
const fEpa = (x) => (x >= 85 ? ["Boa", C.primary] : x >= 70 ? ["Aceitável", C.soil] : ["Baixa", C.warn]);

const ETAPAS = ["Capa", "Uniformidade", "Hidráulica", "Adequab.", "Controle", "Relatório"];

/* ================= APP ================= */
export default function App() {
  const [etapa, setEtapa] = useState(0);
  const [cad, setCad] = useState({});
  const [logo, setLogo] = useState(null);
  const [coletores, setColetores] = useState(Array.from({ length: 4 }, (_, i) => ({ si: i + 1, dist: "", v1: "", v2: "", v3: "", v4: "" })));
  const [bicos, setBicos] = useState(Array.from({ length: 4 }, () => ({ tempo: "", vol: "", pres: "", diam: "" })));
  const [fotos, setFotos] = useState([]);

  const carregarExemplo = () => {
    setCad(EX_CAD);
    setColetores(EX_COL.map(([si, dist, v1, v2, v3, v4]) => ({ si, dist, v1, v2, v3, v4 })));
    setBicos(EX_BICO.map(([_, tempo, vol, pres, diam]) => ({ tempo, vol, pres: pres ?? "", diam: diam ?? "" })));
  };

  const unif = useMemo(() => calcUnif(coletores), [coletores]);
  const hidro = useMemo(() => calcHidro(bicos, cad.canhao === "Sim"), [bicos, cad.canhao]);
  const adeq = useMemo(() => calcAdeq(unif, cad.laminaProjeto), [unif, cad.laminaProjeto]);
  const ctrl = useMemo(() => calcControle(cad), [cad]);

  // Histórico por coordenada (avaliações anteriores no mesmo pivô)
  const [hist, setHist] = useState([]);
  const [msg, setMsg] = useState("");
  const coordKey = useMemo(() => normCoord(cad.coordenadas), [cad.coordenadas]);
  useEffect(() => {
    let vivo = true;
    if (coordKey && typeof window !== "undefined" && window.storage) {
      loadHist(coordKey).then((h) => { if (vivo) setHist(h); });
    } else setHist([]);
    return () => { vivo = false; };
  }, [coordKey]);

  const epa = unif && num(cad.laminaProjeto) ? (unif.lmp / num(cad.laminaProjeto)) * 100 : null;
  const salvar = async () => {
    if (!coordKey) { setMsg("Informe a coordenada para salvar e comparar."); return; }
    if (typeof window === "undefined" || !window.storage) { setMsg("Armazenamento indisponível neste ambiente."); return; }
    const reg = { data: new Date().toISOString().slice(0, 10), empresa: cad.empresa || "", fazenda: cad.fazenda || "",
      cuc: unif ? +unif.cuc.toFixed(1) : null, ud: unif ? +unif.ud.toFixed(1) : null,
      epa: epa != null ? +epa.toFixed(1) : null, adeq: adeq?.adq ?? null, lmp: unif ? +unif.lmp.toFixed(2) : null };
    const novo = [...hist, reg];
    const ok = await saveHist(coordKey, novo);
    if (ok) { setHist(novo); setMsg("Avaliação salva nesta coordenada."); }
    else setMsg("Não foi possível salvar.");
  };

  return (
    <div style={{ background: C.paper, minHeight: "100vh", fontFamily: "'Inter',system-ui,sans-serif", color: C.ink }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Archivo:wght@600;700;800&family=Inter:wght@400;500;600&display=swap');
        * { box-sizing:border-box; }
        .in { width:100%; border:1px solid ${C.line}; background:${C.card}; border-radius:9px; padding:10px 11px; font-size:14px; color:${C.ink}; outline:none; font-family:inherit; }
        .in:focus { border-color:${C.primary}; box-shadow:0 0 0 3px rgba(19,122,99,.12); }
        .inc { text-align:center; padding:8px 4px; font-size:13px; }
        .th { font-size:10px; text-transform:uppercase; color:${C.muted}; font-weight:600; padding:0 3px 6px; text-align:center; }
        .btn { border:none; border-radius:11px; padding:11px 14px; font-size:13px; font-weight:700; font-family:'Archivo',sans-serif; cursor:pointer; }
        @media print { .noprint { display:none !important; } }
      `}</style>

      <div style={{ maxWidth: 470, margin: "0 auto", padding: "20px 16px 110px" }}>
        {etapa === 0 && <Capa cad={cad} setCad={setCad} logo={logo} setLogo={setLogo} carregar={carregarExemplo} avancar={() => setEtapa(1)} temHist={hist.length > 0} />}
        {etapa === 1 && <Uniformidade coletores={coletores} setColetores={setColetores} unif={unif} lproj={cad.laminaProjeto} raio={cad.raio} espac={cad.espacamento} />}
        {etapa === 2 && <Hidraulica bicos={bicos} setBicos={setBicos} hidro={hidro} canhao={cad.canhao === "Sim"} />}
        {etapa === 3 && <Adeq adeq={adeq} lproj={cad.laminaProjeto} />}
        {etapa === 4 && <Controle cad={cad} ctrl={ctrl} unif={unif} epa={epa} />}
        {etapa === 5 && <Relatorio cad={cad} logo={logo} unif={unif} hidro={hidro} adeq={adeq} ctrl={ctrl} epa={epa} hist={hist} salvar={salvar} msg={msg} fotos={fotos} setFotos={setFotos} />}
      </div>

      {/* Navegação por etapas */}
      <nav className="noprint" style={{ position: "fixed", bottom: 0, left: 0, right: 0, background: C.card, borderTop: `1px solid ${C.line}`, display: "flex", maxWidth: 470, margin: "0 auto" }}>
        {ETAPAS.map((e, i) => (
          <button key={e} onClick={() => setEtapa(i)}
            style={{ flex: 1, border: "none", background: "transparent", padding: "11px 2px 10px", cursor: "pointer", borderTop: etapa === i ? `2px solid ${C.primary}` : "2px solid transparent" }}>
            <div style={{ fontFamily: "'Archivo',sans-serif", fontSize: 11, fontWeight: 800, color: etapa === i ? C.primary : C.muted }}>{i}</div>
            <div style={{ fontSize: 9.5, color: etapa === i ? C.ink : C.muted, marginTop: 1 }}>{e}</div>
          </button>
        ))}
      </nav>
    </div>
  );
}

/* ---------- Cabeçalho de seção ---------- */
function Head({ n, titulo, sub }) {
  return (
    <div style={{ marginBottom: 14 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
        <span style={{ fontFamily: "'Archivo',sans-serif", fontSize: 11, fontWeight: 800, color: "#fff", background: C.primary, borderRadius: 7, padding: "2px 8px" }}>{String(n).padStart(2, "0")}</span>
      </div>
      <h1 style={{ fontFamily: "'Archivo',sans-serif", fontWeight: 800, fontSize: 25, margin: "2px 0 3px" }}>{titulo}</h1>
      <p style={{ color: C.muted, fontSize: 13, margin: 0 }}>{sub}</p>
    </div>
  );
}

/* ---------- 0 · CAPA ---------- */
const CAMPOS = [
  ["proprietario", "Nome do proprietário", "text", "Ex.: João da Silva"],
  ["fazenda", "Fazenda", "text", "Ex.: Fazenda Jalapão"],
  ["cidade", "Cidade", "text", "Ex.: Mateiros"],
  ["estado", "Estado", "text", "Ex.: TO"],
  ["comp", "Comprimento à última torre (m)", "number", "Ex.: 374"],
  ["raio", "Raio irrigado (m)", "number", "Ex.: 400"],
  ["espacamento", "Espaçamento entre coletores (m)", "number", "Ex.: 5"],
  ["vazao", "Vazão lida (m³/h)", "number", "Ex.: 351"],
  ["vel", "Velocidade última torre (m/h)", "number", "Ex.: 250"],
  ["pressao", "Pressão de trabalho (kgf/cm²)", "number", "Ex.: 3,8"],
  ["laminaProjeto", "Lâmina de projeto (mm)", "number", "Ex.: 6,56"],
];
function Capa({ cad, setCad, logo, setLogo, carregar, avancar, temHist }) {
  const set = (k, v) => setCad((p) => ({ ...p, [k]: v }));
  const [gps, setGps] = useState("");
  const onLogo = (e) => { const f = e.target.files?.[0]; if (!f) return; const r = new FileReader(); r.onload = () => setLogo(r.result); r.readAsDataURL(f); };
  const capturarGPS = () => {
    if (typeof navigator === "undefined" || !navigator.geolocation) { setGps("GPS indisponível — cole do Google Earth."); return; }
    setGps("Capturando…");
    navigator.geolocation.getCurrentPosition(
      (p) => { set("coordenadas", `${p.coords.latitude.toFixed(6)}, ${p.coords.longitude.toFixed(6)}`); setGps(""); },
      () => setGps("Não foi possível obter o GPS — use o Google Earth."),
      { enableHighAccuracy: true, timeout: 10000 }
    );
  };
  const coordVal = (cad.coordenadas || "").match(/-?\d+[.,]?\d*/g);
  const earthUrl = coordVal && coordVal.length >= 2
    ? `https://earth.google.com/web/search/${coordVal[0].replace(",", ".")},${coordVal[1].replace(",", ".")}`
    : "https://earth.google.com/web/";
  return (
    <div>
      <Head n={0} titulo="Avaliação de Pivô Central" sub="Cadastro do ensaio — preenche o motor uma única vez." />
      <div style={{ position: "relative", borderRadius: 18, overflow: "hidden", marginBottom: 16, border: `1px solid ${C.line}`, boxShadow: "0 8px 22px rgba(11,61,46,.18)" }}>
        <img src={HERO} alt="Pivô central irrigando o campo" style={{ width: "100%", display: "block", filter: "saturate(1.08) contrast(1.04)" }} />
        <div style={{ position: "absolute", inset: 0, background: "linear-gradient(180deg, rgba(19,122,99,.10) 0%, rgba(11,61,46,0) 40%, rgba(11,61,46,.62) 100%)" }} />
        <div style={{ position: "absolute", left: 14, right: 14, bottom: 12 }}>
          <span style={{ display: "inline-block", fontSize: 10, letterSpacing: 2, textTransform: "uppercase", color: "#CFEFE4", fontWeight: 700, marginBottom: 3 }}>Irrigação · campo</span>
          <div style={{ fontFamily: "'Archivo',sans-serif", fontWeight: 800, fontSize: 19, color: "#fff", lineHeight: 1.1, textShadow: "0 1px 6px rgba(0,0,0,.4)" }}>Avaliação técnica do pivô</div>
        </div>
      </div>
      <button className="btn noprint" onClick={carregar} style={{ background: C.ink, color: "#fff", width: "100%", marginBottom: 16 }}>Carregar exemplo completo</button>
      <div style={{ border: `2px dashed ${C.line}`, borderRadius: 14, background: C.card, padding: 14, marginBottom: 18 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <label style={{ cursor: "pointer", flexShrink: 0 }}>
            <div style={{ width: 54, height: 54, borderRadius: 10, background: "#F0F6F3", display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden" }}>
              {logo ? <img src={logo} alt="logo" style={{ width: "100%", height: "100%", objectFit: "contain" }} /> : <span style={{ color: C.primary, fontSize: 22 }}>＋</span>}
            </div>
            <input type="file" accept="image/*" onChange={onLogo} style={{ display: "none" }} />
          </label>
          <div style={{ flex: 1 }}>
            <span style={{ fontSize: 11.5, color: C.muted, fontWeight: 600, display: "block", marginBottom: 5 }}>Empresa (toque na logo para enviar)</span>
            <input className="in" type="text" placeholder="Nome da empresa" value={cad.empresa || ""} onChange={(e) => set("empresa", e.target.value)} />
          </div>
        </div>
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        {CAMPOS.map(([k, lbl, t, ph]) => (
          <label key={k}><span style={{ fontSize: 12.5, color: C.muted, fontWeight: 500, display: "block", marginBottom: 5 }}>{lbl}</span>
            <input className="in" type={t} inputMode={t === "number" ? "decimal" : "text"} placeholder={ph} value={cad[k] || ""} onChange={(e) => set(k, e.target.value)} /></label>
        ))}
        <div>
          <span style={{ fontSize: 12.5, color: C.muted, fontWeight: 500, display: "block", marginBottom: 5 }}>Coordenadas geográficas do pivô</span>
          <div style={{ display: "flex", gap: 8 }}>
            <input className="in" style={{ flex: 1 }} type="text" placeholder="-10.5432, -46.4123" value={cad.coordenadas || ""} onChange={(e) => set("coordenadas", e.target.value)} />
            <button onClick={capturarGPS} title="Capturar por GPS" style={{ border: `1px solid ${C.primary}`, background: "#F0F6F3", color: C.primary, borderRadius: 9, padding: "0 14px", fontWeight: 700, fontFamily: "'Archivo',sans-serif", cursor: "pointer", whiteSpace: "nowrap" }}>📍 GPS</button>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginTop: 6, flexWrap: "wrap" }}>
            <a href={earthUrl} target="_blank" rel="noreferrer" style={{ fontSize: 11.5, color: C.primary, fontWeight: 600, textDecoration: "none" }}>↗ Abrir no Google Earth</a>
            {gps && <span style={{ fontSize: 11.5, color: C.muted }}>{gps}</span>}
            {temHist && <span style={{ fontSize: 11, color: C.soil, fontWeight: 700 }}>● Há avaliação anterior nesta coordenada</span>}
          </div>
        </div>
        <div><span style={{ fontSize: 12.5, color: C.muted, fontWeight: 500, display: "block", marginBottom: 5 }}>Possui canhão hidráulico?</span>
          <div style={{ display: "flex", gap: 8 }}>{["Sim", "Não"].map((o) => {
            const a = cad.canhao === o;
            return <button key={o} onClick={() => set("canhao", o)} style={{ flex: 1, padding: 11, borderRadius: 11, cursor: "pointer", fontWeight: 700, fontFamily: "'Archivo',sans-serif", border: a ? `1.5px solid ${C.primary}` : `1px solid ${C.line}`, background: a ? C.primary : C.card, color: a ? "#fff" : C.ink }}>{o}</button>;
          })}</div>
        </div>
      </div>
      <button className="btn noprint" onClick={avancar}
        style={{ width: "100%", marginTop: 18, background: C.primary, color: "#fff", padding: "15px", fontSize: 16, letterSpacing: 0.3, boxShadow: "0 6px 18px rgba(11,61,46,.22)" }}>
        Iniciar avaliação →
      </button>
    </div>
  );
}

/* ---------- 1 · UNIFORMIDADE ---------- */
function Uniformidade({ coletores, setColetores, unif, lproj, raio, espac }) {
  const set = (i, k, v) => setColetores((p) => p.map((r, x) => (x === i ? { ...r, [k]: v } : r)));
  const add = () => setColetores((p) => [...p, { si: p.length + 1, dist: "", v1: "", v2: "", v3: "", v4: "" }]);
  const del = (i) => setColetores((p) => p.filter((_, x) => x !== i).map((r, x) => ({ ...r, si: x + 1 })));
  const lp = num(lproj);
  const nR = num(raio), nE = num(espac);
  const nGer = nR && nE ? Math.floor(nR / nE) : 0;
  const gerar = () => {
    if (!nGer) return;
    setColetores(Array.from({ length: nGer }, (_, i) => ({ si: i + 1, dist: +(((i + 1) * nE).toFixed(3)), v1: "", v2: "", v3: "", v4: "" })));
  };
  const cd = unif ? unif.v.filter((r) => r.dist != null).map((r) => ({ dist: r.dist, li: +r.li.toFixed(2) })) : [];
  return (
    <div>
      <Head n={1} titulo="Uniformidade" sub="4 leituras de volume (ml) e a distância de cada coletor." />
      {nGer > 0 && (
        <div style={{ display: "flex", alignItems: "center", gap: 10, background: "#F0F6F3", border: `1px solid ${C.line}`, borderRadius: 12, padding: "10px 12px", marginBottom: 12 }}>
          <div style={{ flex: 1, fontSize: 12.5, color: C.ink }}>
            Raio {nR} m ÷ espaçamento {nE} m = <strong>{nGer} coletores</strong>
          </div>
          <button onClick={gerar} className="btn" style={{ background: C.primary, color: "#fff", padding: "9px 12px", fontSize: 12.5 }}>Gerar coletores</button>
        </div>
      )}
      <div style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 14, padding: "10px 6px", overflowX: "auto", marginBottom: 14 }}>
        <table style={{ width: "100%", minWidth: 400, borderCollapse: "collapse" }}>
          <thead><tr><th className="th">Si</th><th className="th">Dist</th><th className="th">V1</th><th className="th">V2</th><th className="th">V3</th><th className="th">V4</th><th className="th"></th></tr></thead>
          <tbody>{coletores.map((r, i) => (
            <tr key={i}><td className="inc" style={{ fontWeight: 700, color: C.primary }}>{r.si}</td>
              {["dist", "v1", "v2", "v3", "v4"].map((k) => <td key={k} style={{ padding: 2 }}><input className="in inc" inputMode="decimal" value={r[k]} onChange={(e) => set(i, k, e.target.value)} /></td>)}
              <td><button onClick={() => del(i)} style={{ border: "none", background: "none", color: C.muted, fontSize: 16, cursor: "pointer" }}>×</button></td></tr>
          ))}</tbody>
        </table>
        <button onClick={add} style={{ width: "100%", marginTop: 8, border: `1px dashed ${C.line}`, background: "#F0F6F3", color: C.primary, borderRadius: 9, padding: 8, fontWeight: 700, fontFamily: "'Archivo',sans-serif", cursor: "pointer" }}>+ coletor</button>
      </div>
      {unif ? (
        <>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 12 }}>
            <Big t="CUC" v={unif.cuc} faixa={fCUC(unif.cuc)} /><Big t="UD" v={unif.ud} faixa={fUD(unif.ud)} />
            <Small t="Lmp" v={unif.lmp} u="mm" /><Small t="LP25" v={unif.lp25} u="mm" />
          </div>
          {cd.length > 1 && <Chart titulo="Lâmina × distância">
            <ComposedChart data={cd} margin={{ top: 6, right: 12, bottom: 16, left: -8 }}>
              <CartesianGrid stroke="#EEE9DC" /><XAxis type="number" dataKey="dist" tick={{ fontSize: 9, fill: C.muted }} /><YAxis tick={{ fontSize: 9, fill: C.muted }} />
              <Tooltip /><Line dataKey="li" name="Lâmina" stroke={C.water} strokeWidth={1.3} dot={{ r: 1.6, fill: C.water, strokeWidth: 0 }} />
              <ReferenceLine y={+unif.lmp.toFixed(2)} stroke={C.primary} strokeWidth={2} label={{ value: `Lmp ${unif.lmp.toFixed(1)}`, fontSize: 9, fill: C.primary, position: "insideTopRight" }} />
              {lp != null && <ReferenceLine y={lp} stroke={C.soil} strokeDasharray="6 4" strokeWidth={2} label={{ value: `proj ${lp}`, fontSize: 9, fill: C.soil, position: "insideBottomRight" }} />}
            </ComposedChart></Chart>}
        </>
      ) : <Vazio />}
    </div>
  );
}

/* ---------- 2 · HIDRÁULICA ---------- */
function Hidraulica({ bicos, setBicos, hidro, canhao }) {
  const [aba, setAba] = useState("dados");
  const set = (i, k, v) => setBicos((p) => p.map((r, x) => (x === i ? { ...r, [k]: v } : r)));
  const add = () => setBicos((p) => [...p, { tempo: "", vol: "", pres: "", diam: "" }]);
  const del = (i) => setBicos((p) => p.filter((_, x) => x !== i));
  const cd = hidro ? hidro.valid.map((r) => ({ pos: r.pos, vazao: +r.vazao.toFixed(2), pres: r.pres })) : [];
  return (
    <div>
      <Head n={2} titulo="Hidráulica · Bocais" sub="Vazão = Volume ÷ Tempo × 3,6. Remanejamento por vazão crescente." />
      <div style={{ display: "flex", gap: 6, background: "#ECEAE0", padding: 4, borderRadius: 11, marginBottom: 14 }}>
        {[["dados", "Lançamento"], ["rem", "Remanejo"], ["graf", "Gráficos"]].map(([id, l]) => (
          <button key={id} onClick={() => setAba(id)} style={{ flex: 1, border: "none", borderRadius: 8, padding: "8px 2px", fontSize: 12, fontWeight: 700, fontFamily: "'Archivo',sans-serif", cursor: "pointer", background: aba === id ? "#fff" : "transparent", color: aba === id ? C.ink : C.muted }}>{l}</button>
        ))}
      </div>
      {aba === "dados" && (
        <div style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 14, padding: "10px 6px", overflowX: "auto" }}>
          <table style={{ width: "100%", minWidth: 400, borderCollapse: "collapse" }}>
            <thead><tr><th className="th">#</th><th className="th">Tempo</th><th className="th">Vol</th><th className="th">Pressão</th><th className="th">Ø</th><th className="th">Vazão</th><th className="th"></th></tr></thead>
            <tbody>{bicos.map((r, i) => {
              const t = num(r.tempo), v = num(r.vol); const vz = t && v != null ? ((v / t) * 3.6).toFixed(2) : "—";
              return <tr key={i}><td className="inc" style={{ fontWeight: 700, color: C.primary }}>{i + 1}</td>
                {["tempo", "vol", "pres", "diam"].map((k) => <td key={k} style={{ padding: 2 }}><input className="in inc" inputMode="decimal" value={r[k]} onChange={(e) => set(i, k, e.target.value)} /></td>)}
                <td className="inc" style={{ fontWeight: 700 }}>{vz}</td><td><button onClick={() => del(i)} style={{ border: "none", background: "none", color: C.muted, fontSize: 16, cursor: "pointer" }}>×</button></td></tr>;
            })}</tbody>
          </table>
          <button onClick={add} style={{ width: "100%", marginTop: 8, border: `1px dashed ${C.line}`, background: "#F0F6F3", color: C.primary, borderRadius: 9, padding: 8, fontWeight: 700, fontFamily: "'Archivo',sans-serif", cursor: "pointer" }}>+ bico</button>
        </div>
      )}
      {aba === "rem" && (hidro ? (
        <div style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 14, padding: "8px 4px", maxHeight: 420, overflowY: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead><tr><th className="th">Atual</th><th className="th">Vazão</th><th className="th">Ø</th><th className="th">→ Nova</th><th className="th">Mover</th></tr></thead>
            <tbody>{hidro.mapping.map((m) => {
              const cor = m.delta > 0 ? C.up : m.delta < 0 ? C.warn : C.muted;
              return <tr key={m.pos} style={{ borderTop: `1px solid ${C.paper}`, background: m.canhao ? "#FBF3EC" : "#fff" }}>
                <td className="inc" style={{ fontWeight: 700, color: m.canhao ? C.soil : C.ink }}>{m.pos}</td><td className="inc">{m.vazao.toFixed(2)}</td><td className="inc" style={{ color: C.muted }}>{m.diam ?? "—"}</td>
                <td className="inc" style={{ fontWeight: 800, color: m.canhao ? C.soil : C.primary }}>{m.novaPos}</td>
                <td className="inc" style={{ fontWeight: 700, color: m.canhao ? C.soil : cor, fontSize: 11 }}>{m.canhao ? "Canhão" : (m.delta > 0 ? "↑" : m.delta < 0 ? "↓" : "•") + (m.delta ? " " + Math.abs(m.delta) : "")}</td></tr>;
            })}</tbody>
          </table>
        </div>
      ) : <Vazio />)}
      {aba === "graf" && (hidro && cd.length > 1 ? (
        <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
          <Chart titulo="Vazão dos aspersores por posição">
            <ComposedChart data={cd} margin={{ top: 6, right: 10, bottom: 14, left: -12 }}><CartesianGrid stroke="#EEE9DC" /><XAxis dataKey="pos" tick={{ fontSize: 9, fill: C.muted }} /><YAxis tick={{ fontSize: 9, fill: C.muted }} /><Tooltip />
              <Line dataKey="vazao" name="Vazão" stroke={C.water} strokeWidth={1.2} dot={{ r: 1.5, fill: C.water, strokeWidth: 0 }} /><ReferenceLine y={+hidro.media.toFixed(2)} stroke={C.primary} strokeDasharray="5 4" /></ComposedChart></Chart>
          <Chart titulo="Pressão por posição">
            <ComposedChart data={cd} margin={{ top: 6, right: 10, bottom: 14, left: -12 }}><CartesianGrid stroke="#EEE9DC" /><XAxis dataKey="pos" tick={{ fontSize: 9, fill: C.muted }} /><YAxis tick={{ fontSize: 9, fill: C.muted }} domain={[0, "auto"]} /><Tooltip />
              <Line dataKey="pres" name="Pressão" stroke={C.soil} strokeWidth={1.2} dot={{ r: 1.5, fill: C.soil, strokeWidth: 0 }} connectNulls /></ComposedChart></Chart>
          <Chart titulo="Vazão ajustada (pós-remanejamento)">
            <ComposedChart data={hidro.ajustado} margin={{ top: 6, right: 10, bottom: 14, left: -12 }}><CartesianGrid stroke="#EEE9DC" /><XAxis dataKey="novaPos" tick={{ fontSize: 9, fill: C.muted }} /><YAxis tick={{ fontSize: 9, fill: C.muted }} /><Tooltip />
              <Line dataKey="vazao" name="Ajustada" stroke={C.water} dot={{ r: 1.5, fill: C.water, strokeWidth: 0 }} strokeWidth={1.4} /></ComposedChart></Chart>
        </div>
      ) : <Vazio />)}
    </div>
  );
}

/* ---------- 3 · ADEQUABILIDADE ---------- */
function Adeq({ adeq, lproj }) {
  const lp = num(lproj);
  if (!adeq) return <div><Head n={3} titulo="Adequabilidade" sub="Frações da área acima/abaixo da lâmina de projeto." /><Vazio /></div>;
  const cruz = adeq.adq != null && adeq.adq < 100 && lp != null ? { freq: adeq.adq, lamina: lp } : null;
  return (
    <div>
      <Head n={3} titulo="Adequabilidade" sub="Quanto da área recebe a lâmina de projeto." />
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 16 }}>
        <Big t="≥ projeto" v={adeq.adq} faixa={["adequada", C.primary]} suf />
        <Big t="< projeto" v={adeq.adq == null ? null : +(100 - adeq.adq).toFixed(1)} faixa={["déficit", C.warn]} suf />
      </div>
      <Chart titulo="Curva de adequabilidade" footer={<AdeqAreaLegend />}>
        <ComposedChart data={adeq.curva} margin={{ top: 8, right: 12, bottom: 16, left: -6 }}>
          <CartesianGrid stroke="#EEE9DC" /><XAxis type="number" dataKey="freq" domain={[0, 100]} tick={{ fontSize: 9, fill: C.muted }} /><YAxis tick={{ fontSize: 9, fill: C.muted }} /><Tooltip labelFormatter={(l) => `${l}% da área`} /><Legend wrapperStyle={{ fontSize: 10 }} />
          {cruz && <ReferenceArea x1={0} x2={cruz.freq} fill={C.primary} fillOpacity={0.1} label={{ value: `≥ projeto ${adeq.adq}%`, fontSize: 9, fill: C.primary, position: "insideTop" }} />}
          {cruz && <ReferenceArea x1={cruz.freq} x2={100} fill={C.warn} fillOpacity={0.1} label={{ value: `< projeto ${(100 - adeq.adq).toFixed(1)}%`, fontSize: 9, fill: C.warn, position: "insideTop" }} />}
          <Line dataKey="lamina" name="Lâmina" stroke={C.water} strokeWidth={2.2} dot={false} />
          <ReferenceLine y={+adeq.lmp.toFixed(2)} stroke={C.primary} strokeDasharray="5 4" label={{ value: `média ${adeq.lmp.toFixed(1)}`, fontSize: 9, fill: C.primary, position: "insideBottomRight" }} />
          {lp != null && <ReferenceLine y={lp} stroke={C.soil} strokeWidth={2} label={{ value: `projeto ${lp}`, fontSize: 9, fill: C.soil, position: "insideTopLeft" }} />}
          {cruz && <ReferenceDot x={cruz.freq} y={cruz.lamina} r={5} fill={C.soil} stroke="#fff" strokeWidth={2} />}
        </ComposedChart></Chart>
    </div>
  );
}

/* ---------- 4 · TABELA DE CONTROLE ---------- */
function Controle({ cad, ctrl, unif, epa }) {
  if (!ctrl) return <div><Head n={4} titulo="Tabela de Controle" sub="Parâmetros de operação e percentímetro." /><Vazio /></div>;
  const params = [["Comprimento", cad.comp, "m"], ["Vazão lida", cad.vazao, "m³/h"], ["Velocidade", cad.vel, "m/h"], ["Raio irrigado", cad.raio, "m"], ["Pressão", cad.pressao, "kgf/cm²"]];
  return (
    <div>
      <Head n={4} titulo="Tabela de Controle" sub="Parâmetros de operação e percentímetro de 10% a 100%." />
      <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 14 }}>
        {params.map(([t, v, u]) => (
          <div key={t} style={{ flex: "1 0 28%", background: C.card, border: `1px solid ${C.line}`, borderRadius: 11, padding: "9px 10px" }}>
            <div style={{ fontSize: 10, color: C.muted, fontWeight: 600 }}>{t}</div>
            <div style={{ fontFamily: "'Archivo',sans-serif", fontSize: 15, fontWeight: 700 }}>{v || "—"}<span style={{ fontSize: 10, color: C.muted }}> {u}</span></div>
          </div>
        ))}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 16 }}>
        <Dark t="Tempo de giro a 100%" v={ctrl.tempo.toFixed(2)} u="h" />
        <Dark t="Lâmina bruta a 100%" v={ctrl.lamina100.toFixed(2)} u="mm" />
      </div>
      {(unif || epa != null) && (
        <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 16 }}>
          {unif && <Badge l="CUC" v={unif.cuc.toFixed(1)} f={fCUC(unif.cuc)} />}
          {unif && <Badge l="UD" v={unif.ud.toFixed(1)} f={fUD(unif.ud)} />}
          {epa != null && <Badge l="Epa" v={epa.toFixed(1)} f={fEpa(epa)} />}
        </div>
      )}
      <div style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 14, overflow: "hidden" }}>
        <div style={{ maxHeight: 420, overflowY: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead><tr>
              <th className="th" style={{ position: "sticky", top: 0, background: C.card }}>Perc. %</th>
              <th className="th" style={{ position: "sticky", top: 0, background: C.card }}>Veloc. (m/h)</th>
              <th className="th" style={{ position: "sticky", top: 0, background: C.card }}>Tempo/volta (h)</th>
              <th className="th" style={{ position: "sticky", top: 0, background: C.card }}>Lâmina (mm)</th>
            </tr></thead>
            <tbody>{ctrl.tabela.map((r) => (
              <tr key={r.p} style={{ borderTop: `1px solid ${C.paper}`, background: r.p % 10 === 0 ? "#F0F6F3" : "#fff" }}>
                <td className="inc" style={{ fontWeight: 700, color: C.primary }}>{r.p}</td>
                <td className="inc">{r.vel.toFixed(1)}</td>
                <td className="inc">{r.tv.toFixed(2)}</td>
                <td className="inc" style={{ fontWeight: 600 }}>{r.lam.toFixed(2)}</td>
              </tr>
            ))}</tbody>
          </table>
        </div>
      </div>
      <p style={{ fontSize: 11, color: C.muted, marginTop: 8 }}>Linhas destacadas marcam cada 10% do percentímetro. Lâmina e tempo são inversamente proporcionais ao percentímetro.</p>
    </div>
  );
}

/* ---------- 5 · RELATÓRIO ---------- */
function Relatorio({ cad, logo, unif, hidro, adeq, ctrl, epa, hist, salvar, msg, fotos, setFotos }) {
  const textos = [];
  if (unif) { textos.push(`CUC de ${unif.cuc.toFixed(1)}% — ${fCUC(unif.cuc)[0].toLowerCase()}.`); textos.push(`UD de ${unif.ud.toFixed(1)}% — ${fUD(unif.ud)[0].toLowerCase()}.`); }
  if (adeq?.adq != null) textos.push(`${adeq.adq}% da área recebe a lâmina de projeto ou mais; ${(100 - adeq.adq).toFixed(1)}% ficam em déficit.`);
  if (unif && unif.cuc < 80) textos.push("Recomenda-se o remanejamento de bocais (Seção 2) antes de ajustar a lâmina pelo percentímetro.");

  const ucd = unif ? unif.v.filter((r) => r.dist != null).map((r) => ({ dist: r.dist, li: +r.li.toFixed(2) })) : [];
  const hcd = hidro ? hidro.valid.map((r) => ({ pos: r.pos, vazao: +r.vazao.toFixed(2), pres: r.pres })) : [];
  const lp = num(cad.laminaProjeto);
  const cruz = adeq?.adq != null && adeq.adq < 100 && lp != null ? { freq: adeq.adq, lamina: lp } : null;

  const getCharts = () => {
    try { return Array.from(document.querySelectorAll("#report-area .recharts-wrapper svg")).map((s) => s.outerHTML); }
    catch (e) { return []; }
  };

  const ABNT_CSS = `
    @page { size: A4; margin: 3cm 2cm 2cm 3cm; }
    @page { @top-right { content: counter(page); font-family:Arial,Helvetica,sans-serif; font-size:10pt; } }
    * { box-sizing: border-box; }
    body { font-family:Arial, Helvetica, sans-serif; font-size:12pt; color:#000; line-height:1.5; text-align:justify; margin:0; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
    h1 { font-size:14pt; font-weight:bold; color:#003366; text-transform:uppercase; margin:18pt 0 12pt; page-break-before:auto; }
    h1.nobreak { page-break-before:avoid; }
    h1#k_sum, h1#k_anexo { page-break-before:always; }
    h2 { font-size:12pt; font-weight:bold; color:#003366; margin:14pt 0 8pt; }
    p { text-indent:1.25cm; margin:0 0 8pt; }
    p.flush { text-indent:0; }
    ul { margin:0 0 8pt 0; }
    table { width:100%; border-collapse:collapse; margin:2pt 0; font-size:10pt; }
    th,td { padding:4pt 6pt; text-align:center; vertical-align:middle; }
    thead th { font-weight:bold; border-top:1.5px solid #000; border-bottom:1px solid #000; }
    tbody tr:last-child td { border-bottom:1.5px solid #000; }
    .tabcap,.figcap { font-size:10pt; text-indent:0; margin:12pt 0 2pt; }
    .figcap { text-align:center; }
    .tabsrc,.figsrc { font-size:10pt; text-indent:0; margin:2pt 0 14pt; }
    .figsrc { text-align:center; }
    .fig { text-align:center; page-break-inside:avoid; }
    .fig svg { width:100%; height:auto; max-width:100%; }
    .foto { display:block; margin:0 auto; max-width:100%; max-height:19cm; height:auto; }
    .eq { text-align:center; margin:10pt 0; position:relative; }
    .eq .num { position:absolute; right:0; }
    .capa { text-align:center; page-break-after:always; padding-top:30pt; }
    .capa .inst { font-size:14pt; font-weight:bold; text-transform:uppercase; }
    .capa .tit { font-size:16pt; font-weight:bold; color:#003366; margin:90pt 0 60pt; line-height:1.4; }
    .capa img { max-width:130px; height:auto; display:block; margin:0 auto 18pt; }
    .capa .meta { font-size:12pt; margin-top:80pt; }
    .sum .row { display:flex; align-items:flex-end; text-indent:0; margin:4pt 0; font-size:12pt; }
    .sum .row .it { white-space:nowrap; }
    .sum .row .dots { flex:1; border-bottom:1px dotted #555; margin:0 4px 4px; }
    .sum .row .pg { white-space:nowrap; min-width:1.6em; text-align:right; font-variant-numeric:tabular-nums; }
    .sum .subrow { padding-left:1cm; font-size:11pt; }
    table.rpt { width:100%; border-collapse:collapse; }
    table.rpt > thead { display:table-header-group; }
    table.rpt > tfoot { display:table-footer-group; }
    table.rpt > thead > tr > td, table.rpt > tfoot > tr > td, table.rpt > tbody > tr > td { border:none; padding:0; text-align:left; vertical-align:top; }
    .rh { font-size:7.5pt; display:flex; justify-content:space-between; align-items:center; border-bottom:0.5px solid #999; padding-bottom:3px; margin-bottom:12px; }
    .rf { font-size:7.5pt; display:flex; justify-content:space-between; align-items:center; border-top:0.5px solid #999; padding-top:3px; margin-top:12px; }
    .rh .org, .rf .org { display:flex; align-items:center; gap:5px; font-weight:bold; }
    .rh .org img, .rf .org img { height:11px; width:auto; }
    .bar { background:#003366; color:#fff; padding:12px 16px; display:flex; justify-content:space-between; align-items:center; font-weight:bold; font-family:Arial; }
    .bar button { background:#fff; color:#003366; border:none; border-radius:6px; padding:8px 14px; font-weight:bold; cursor:pointer; }
    @media screen { body{ background:#e7e7e7; } .sheet{ background:#fff; width:210mm; margin:0 auto; padding:3cm 2cm 2cm 3cm; } }
    @media print { .bar{ display:none; } h1{ page-break-before:auto; } h1.nobreak{ page-break-before:avoid; } h1#k_sum, h1#k_anexo{ page-break-before:always; } }
  `;

  const docHTML = (autoprint) => {
    const D = new Date().toLocaleDateString("pt-BR");
    const emp = cad.empresa || "—";
    const v = (x, d = 1) => (x == null ? "—" : (+x).toFixed(d));
    const cuc = unif ? v(unif.cuc) : "—", ud = unif ? v(unif.ud) : "—";
    const lmp = unif ? v(unif.lmp, 2) : "—", lp25 = unif ? v(unif.lp25, 2) : "—";
    const epaT = epa != null ? v(epa) : "—", adeqT = adeq?.adq != null ? v(adeq.adq) : "—";
    const lpT = lp != null ? v(lp, 2) : "—";
    const nCol = unif ? unif.n : 0, nBic = hidro ? hidro.n : 0;
    const totalQ = hidro ? hidro.valid.reduce((a, r) => a + r.vazao, 0) : null;
    const charts = getCharts();
    const tbl = (heads, rows) => `<table><thead><tr>${heads.map((h) => `<th>${h}</th>`).join("")}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table>`;

    const t1 = tbl(["Parâmetro", "Valor"], [
      ["Proprietário", cad.proprietario || "—"], ["Fazenda", cad.fazenda || "—"],
      ["Município / UF", `${cad.cidade || "—"} / ${cad.estado || "—"}`], ["Coordenadas", cad.coordenadas || "—"],
      ["Comprimento à última torre (m)", cad.comp || "—"], ["Raio irrigado (m)", cad.raio || "—"],
      ["Espaçamento entre coletores (m)", cad.espacamento || "—"], ["Vazão lida (m³/h)", cad.vazao || "—"],
      ["Velocidade na última torre (m/h)", cad.vel || "—"], ["Pressão de trabalho (kgf/cm²)", cad.pressao || "—"],
      ["Lâmina de projeto (mm)", cad.laminaProjeto || "—"], ["Canhão hidráulico", cad.canhao || "—"],
    ]);
    const t2 = tbl(["Indicador", "Valor", "Classificação"], [
      ["CUC (%)", cuc, unif ? fCUC(unif.cuc)[0] : "—"], ["UD (%)", ud, unif ? fUD(unif.ud)[0] : "—"],
      ["Eficiência de aplicação – Epa (%)", epaT, epa != null ? fEpa(epa)[0] : "—"],
      ["Lâmina média ponderada – Lmp (mm)", lmp, "—"], ["Lâmina dos 25% menores – LP25 (mm)", lp25, "—"],
      ["Área com lâmina ≥ projeto (%)", adeqT, "—"],
    ]);
    const t3 = hidro ? tbl(["Nova posição", "Vazão ajustada (m³/h)", "Posição atual", "Ø (mm)"],
      [...hidro.mapping].sort((a, b) => a.novaPos - b.novaPos).map((m) => [m.novaPos + (m.canhao ? " (canhão)" : ""), m.vazao.toFixed(2), m.pos, m.diam ?? "—"])) : "";
    const t4 = ctrl ? tbl(["Percentímetro (%)", "Velocidade (m/h)", "Tempo/volta (h)", "Lâmina bruta (mm)"],
      ctrl.tabela.map((r) => [r.p, r.vel.toFixed(1), r.tv.toFixed(2), r.lam.toFixed(2)])) : "";

    const figCaps = ["Perfil da lâmina aplicada em função da distância ao centro do pivô.", "Pressão de serviço por posição de bocal.", "Vazão dos aspersores por posição.", "Vazão ajustada após o remanejamento dos bocais.", "Curva de adequabilidade da irrigação. A área sombreada em verde indica a fração da área com lâmina igual ou superior à de projeto; a área em vermelho, a fração com lâmina inferior à de projeto."];
    const figuras = charts.map((svg, i) => `<div class="fig"><p class="figcap">Figura ${i + 1} – ${figCaps[i] || ""}</p>${svg}<p class="figsrc">Fonte: Elaborado pelo autor.</p></div>`).join("");
    const temFotos = fotos && fotos.length > 0;
    const fotosFigs = temFotos ? fotos.map((f, i) => `<div class="fig"><p class="figcap">Figura ${charts.length + i + 1} – Registro fotográfico do ensaio. Data: ${f.date} · Coordenadas: ${cad.coordenadas || "—"}.</p><img class="foto" src="${f.url}" alt="Registro do ensaio"><p class="figsrc">Fonte: Acervo do ensaio.</p></div>`).join("") : "";
    const anexo = temFotos ? `<h1 id="k_anexo">ANEXO A – REGISTRO FOTOGRÁFICO DO ENSAIO</h1>${fotosFigs}` : "";

    const recs = [];
    if (unif && unif.cuc < 80) recs.push("Executar o remanejamento dos bocais conforme a Tabela 3, dispondo-os em ordem crescente de vazão do centro para a extremidade, elevando a uniformidade de aplicação.");
    if (adeq?.adq != null && adeq.adq < 80) recs.push("Ajustar o tempo de funcionamento pelo percentímetro e revisar a pressão de serviço para reduzir a fração da área em déficit hídrico.");
    recs.push("Repetir a avaliação periodicamente, mantendo o registro por coordenada para acompanhamento da evolução do equipamento.");

    const compBlock = (() => {
      if (!hist || hist.length === 0)
        return `<p>Esta é a primeira avaliação registrada para a coordenada informada (${cad.coordenadas || "—"}); não há avaliação anterior para comparação.</p>`;
      const ant = hist[hist.length - 1];
      const at = { cuc: unif ? +unif.cuc.toFixed(1) : null, ud: unif ? +unif.ud.toFixed(1) : null, epa: epa != null ? +epa.toFixed(1) : null, adq: adeq?.adq ?? null };
      const ls = [["CUC (%)", ant.cuc, at.cuc], ["UD (%)", ant.ud, at.ud], ["Epa (%)", ant.epa, at.epa], ["Área com lâmina ≥ projeto (%)", ant.adeq, at.adq]];
      const rows = ls.map(([nome, a, b]) => { const d = a != null && b != null ? (b - a).toFixed(1) : null; return [nome, a == null ? "—" : a, b == null ? "—" : b, d == null ? "—" : (d > 0 ? "+" : "") + d]; });
      return `<p>A Tabela 5 compara os indicadores desta avaliação com os da avaliação anterior registrada na mesma coordenada (${cad.coordenadas || "—"}), realizada em ${ant.data}.</p>` +
        `<p class="tabcap">Tabela 5 – Comparação com a avaliação anterior na mesma coordenada.</p>` +
        tbl([`Indicador`, `Anterior (${ant.data})`, `Atual`, `Variação`], rows) +
        `<p class="tabsrc">Fonte: Elaborado pelo autor.</p>`;
    })();

    const sec = (n, t, key, sub) => `<div class="sum row${sub ? " subrow" : ""}"><span class="it">${n ? n + " " : ""}${t}</span><span class="dots"></span><span class="pg" id="${key}"></span></div>`;

    const pag = autoprint ? "setTimeout(function(){window.print();},450);" : "";
    const ordr = ["k_resumo", "k_sum", "k1", "k2", "k3", "k4", "k5", "k6", "k7", "k8"];
    const kys = ["p_resumo", "p_sum", "p1", "p2", "p3", "p4", "p5", "p6", "p7", "p8"];
    if (temFotos) { ordr.push("k_anexo"); kys.push("p_anexo"); }
    const pagScript = `<script>(function(){function paginate(){var pageH=(297-30-20-18)/25.4*96;var order=${JSON.stringify(ordr)};var keys=${JSON.stringify(kys)};var els=order.map(function(id){return document.getElementById(id);});var tops=els.map(function(e){return e?e.offsetTop:0;});var start=[];start[0]=2;for(var i=1;i<order.length;i++){var h=tops[i]-tops[i-1];start[i]=start[i-1]+Math.max(1,Math.ceil(h/pageH));}for(var j=0;j<order.length;j++){var sp=document.getElementById(keys[j]);if(sp&&keys[j]!=='p_sum')sp.textContent=start[j];}var s5=document.getElementById('k5'),s51=document.getElementById('k51'),p51=document.getElementById('p51');if(s5&&s51&&p51){var i5=order.indexOf('k5');p51.textContent=start[i5]+Math.floor((s51.offsetTop-s5.offsetTop)/pageH);}}window.addEventListener('load',function(){try{paginate();}catch(e){}${pag}});})();<\/script>`;

    return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Relatório — Avaliação de Pivô Central</title><style>${ABNT_CSS}</style></head><body>
<div class="bar"><span>Relatório técnico — Avaliação de Pivô Central</span><button onclick="window.print()">Imprimir / Salvar em PDF</button></div>
<div class="sheet">

  <section class="capa">
    ${logo ? `<img src="${logo}" alt="logomarca">` : ""}
    <div class="inst">${emp}</div>
    <div class="tit">RELATÓRIO TÉCNICO DE AVALIAÇÃO<br>DE SISTEMA DE IRRIGAÇÃO POR PIVÔ CENTRAL</div>
    <div>${cad.fazenda ? "Fazenda " + cad.fazenda : ""}</div>
    <div class="meta">${cad.cidade || ""}${cad.estado ? " — " + cad.estado : ""}<br>${D}</div>
  </section>

  <table class="rpt">
  <thead><tr><td><div class="rh"><span class="org">${logo ? `<img src="${logo}" alt="logo">` : ""}${emp}</span><span>Avaliação de Pivô Central</span><span>${D}</span></div></td></tr></thead>
  <tfoot><tr><td><div class="rf"><span class="org">${logo ? `<img src="${logo}" alt="logo">` : ""}${emp}</span><span>Versão 1.0</span><span>Relatório técnico</span></div></td></tr></tfoot>
  <tbody><tr><td>

  <h1 class="nobreak" id="k_resumo">RESUMO</h1>
  <p>Este relatório apresenta a avaliação de desempenho de um sistema de irrigação por pivô central
  ${cad.fazenda ? "instalado na Fazenda " + cad.fazenda : ""}${cad.cidade ? ", em " + cad.cidade + "/" + (cad.estado || "") : ""}.
  Avaliaram-se a uniformidade de aplicação de água, as condições hidráulicas dos bocais, a adequabilidade da
  irrigação em relação à lâmina de projeto e elaborou-se a tabela de controle do percentímetro. Foram obtidos
  coeficiente de uniformidade de Christiansen (CUC) de ${cuc}%, uniformidade de distribuição (UD) de ${ud}% e
  eficiência de aplicação de ${epaT}%, com ${adeqT}% da área recebendo lâmina igual ou superior à de projeto
  (${lpT} mm). Recomenda-se o remanejamento dos bocais em ordem crescente de vazão para elevar a uniformidade.</p>
  <p class="flush"><b>Palavras-chave:</b> irrigação; pivô central; uniformidade; adequabilidade.</p>

  <h1 id="k_sum">SUMÁRIO</h1>
  <div class="sum">
    ${sec("", "RESUMO", "p_resumo")}${sec("1", "INTRODUÇÃO", "p1")}${sec("2", "OBJETIVOS", "p2")}${sec("3", "MATERIAIS E MÉTODOS", "p3")}
    ${sec("4", "DESENVOLVIMENTO", "p4")}${sec("5", "RESULTADOS", "p5")}${sec("5.1", "Comparação com avaliação anterior", "p51", true)}
    ${sec("6", "DISCUSSÃO", "p6")}${sec("7", "CONCLUSÕES", "p7")}${sec("8", "RECOMENDAÇÕES", "p8")}
    ${temFotos ? sec("ANEXO A", "REGISTRO FOTOGRÁFICO", "p_anexo") : ""}
  </div>

  <h1 id="k1">1 INTRODUÇÃO</h1>
  <p>A irrigação por pivô central é amplamente empregada na agricultura irrigada por permitir a aplicação de água
  de forma mecanizada sobre grandes áreas. A eficiência do sistema depende da uniformidade de distribuição da
  água, das condições hidráulicas dos emissores e da correta lâmina aplicada. A avaliação periódica do equipamento
  permite identificar desvios e orientar ajustes que reduzem perdas e melhoram o aproveitamento hídrico.</p>

  <h1 id="k2">2 OBJETIVOS</h1>
  <p>Avaliar o desempenho do sistema quanto à uniformidade de aplicação (CUC e UD), às condições hidráulicas dos
  bocais e à adequabilidade da irrigação, propor o remanejamento dos bocais e disponibilizar a tabela de controle
  operacional do percentímetro.</p>

  <h1 id="k3">3 MATERIAIS E MÉTODOS</h1>
  <p>A caracterização do equipamento avaliado é apresentada na Tabela 1. O ensaio de uniformidade foi realizado
  com coletores dispostos radialmente, espaçados a cada ${cad.espacamento || "—"} m, considerando-se a área de
  captação de 78,54 cm² por coletor. A lâmina coletada em cada ponto foi obtida a partir da média de quatro
  leituras de volume.</p>
  <p class="tabcap">Tabela 1 – Dados cadastrais do equipamento.</p>${t1}<p class="tabsrc">Fonte: Elaborado pelo autor.</p>
  <p>Os indicadores foram calculados pelas equações a seguir, em que S<sub>i</sub> é o peso radial do coletor,
  L<sub>i</sub> a lâmina coletada e Lmp a lâmina média ponderada:</p>
  <p class="eq">CUC = [1 − Σ(S<sub>i</sub>·|L<sub>i</sub> − Lmp|) ÷ (Lmp·ΣS<sub>i</sub>)] × 100 <span class="num">(1)</span></p>
  <p class="eq">UD = (LP25 ÷ Lmp) × 100 <span class="num">(2)</span></p>
  <p class="eq">Q = (V ÷ t) × 3,6 <span class="num">(3)</span></p>
  <p class="eq">T = (2·π·L) ÷ V<sub>t</sub> <span class="num">(4)</span></p>
  <p class="eq">Lâmina<sub>100%</sub> = (T·Q) ÷ [10·(π·R² ÷ 10000)] <span class="num">(5)</span></p>
  <p>A adequabilidade foi definida como a fração da área que recebe lâmina igual ou superior à de projeto,
  obtida por interpolação na curva de frequência acumulada ponderada pela área. O remanejamento dos bocais
  seguiu o critério de vazão crescente do centro à extremidade, mantendo-se o canhão hidráulico fixo na ponta.</p>

  <h1 id="k4">4 DESENVOLVIMENTO</h1>
  <p>Foram avaliados ${nCol} coletores no ensaio de uniformidade e ${nBic} bocais no levantamento hidráulico.
  ${totalQ != null ? "A vazão total medida foi de " + totalQ.toFixed(0) + " m³/h." : ""} Os dados coletados em campo
  foram processados conforme as equações (1) a (5), gerando os indicadores e os perfis apresentados na seção de resultados.</p>

  <h1 id="k5">5 RESULTADOS</h1>
  <p>Os indicadores de desempenho são apresentados na Tabela 2.</p>
  <p class="tabcap">Tabela 2 – Indicadores de desempenho da avaliação.</p>${t2}<p class="tabsrc">Fonte: Elaborado pelo autor.</p>
  ${figuras}
  ${t3 ? `<p class="tabcap">Tabela 3 – Remanejamento dos bocais e vazões ajustadas.</p>${t3}<p class="tabsrc">Fonte: Elaborado pelo autor.</p>` : ""}
  ${t4 ? `<p class="tabcap">Tabela 4 – Tabela de controle do percentímetro.</p>${t4}<p class="tabsrc">Fonte: Elaborado pelo autor.</p>` : ""}

  <h2 id="k51">5.1 Comparação com avaliação anterior</h2>
  ${compBlock}

  <h1 id="k6">6 DISCUSSÃO</h1>
  ${textos.length ? textos.map((t) => `<p>${t}</p>`).join("") : "<p>—</p>"}

  <h1 id="k7">7 CONCLUSÕES</h1>
  <p>O sistema apresentou CUC de ${cuc}% e UD de ${ud}%, com eficiência de aplicação de ${epaT}%. A análise de
  adequabilidade indicou que ${adeqT}% da área recebe lâmina igual ou superior à de projeto (${lpT} mm),
  permanecendo o restante em déficit. Os resultados subsidiam as recomendações da seção seguinte.</p>

  <h1 id="k8">8 RECOMENDAÇÕES</h1>
  <ul>${recs.map((r) => `<li style="text-align:justify;">${r}</li>`).join("")}</ul>
  ${anexo}

  </td></tr></tbody></table>
</div>${pagScript}</body></html>`;
  };

  const imprimir = () => {
    const w = window.open("", "_blank");
    if (!w) { window.print(); return; }
    w.document.write(docHTML(true)); w.document.close(); w.focus();
  };
  const baixarHTML = () => {
    const blob = new Blob([docHTML(false)], { type: "text/html;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = "relatorio-pivo-" + (cad.fazenda || "avaliacao").replace(/\s+/g, "_") + ".html";
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1500);
  };
  const addFotos = (e) => {
    const files = Array.from(e.target.files || []);
    files.forEach((f) => compressImg(f, (url) => setFotos((p) => [...p, { url, date: new Date().toLocaleDateString("pt-BR") }])));
    e.target.value = "";
  };
  const delFoto = (i) => setFotos((p) => p.filter((_, x) => x !== i));

  return (
    <div>
      <div id="report-area">
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, marginBottom: 14 }}>
        <div><Head n={5} titulo="Relatório final" sub={`${cad.fazenda || "—"} · ${cad.cidade || "—"}/${cad.estado || "—"}`} /></div>
        {(logo || cad.empresa) && (
          <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 4, flexShrink: 0 }}>
            {logo && <img src={logo} alt="logo" style={{ width: 56, height: 56, objectFit: "contain" }} />}
            {cad.empresa && <span style={{ fontSize: 11, fontWeight: 700, color: C.ink, textAlign: "right", maxWidth: 110 }}>{cad.empresa}</span>}
          </div>
        )}
      </div>

      {/* Indicadores */}
      <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 14 }}>
        {unif && <Badge l="CUC" v={unif.cuc.toFixed(1)} f={fCUC(unif.cuc)} />}
        {unif && <Badge l="UD" v={unif.ud.toFixed(1)} f={fUD(unif.ud)} />}
        {adeq?.adq != null && <Badge l="Adequação" v={adeq.adq} f={["", C.soil]} />}
      </div>

      {/* Parâmetros calculados */}
      {ctrl && <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 16 }}>
        <Dark t="Tempo de giro a 100%" v={ctrl.tempo.toFixed(2)} u="h" /><Dark t="Lâmina bruta a 100%" v={ctrl.lamina100.toFixed(2)} u="mm" />
      </div>}

      {/* Gráficos consolidados (espaço integral) */}
      <div style={{ display: "flex", flexDirection: "column", gap: 14, marginBottom: 16 }}>
        {ucd.length > 1 && <Chart titulo="Uniformidade — lâmina × distância" h={300}>
          <ComposedChart data={ucd} margin={{ top: 6, right: 12, bottom: 14, left: -10 }}><CartesianGrid stroke="#EEE9DC" /><XAxis type="number" dataKey="dist" tick={{ fontSize: 9, fill: C.muted }} /><YAxis tick={{ fontSize: 9, fill: C.muted }} /><Tooltip />
            <Line dataKey="li" name="Lâmina" stroke={C.water} strokeWidth={1.3} dot={{ r: 1.6, fill: C.water, strokeWidth: 0 }} />
            <ReferenceLine y={+unif.lmp.toFixed(2)} stroke={C.primary} strokeWidth={2} label={{ value: `Lmp ${unif.lmp.toFixed(1)}`, fontSize: 9, fill: C.primary, position: "insideTopRight" }} />
            {lp != null && <ReferenceLine y={lp} stroke={C.soil} strokeDasharray="6 4" strokeWidth={2} label={{ value: `proj ${lp}`, fontSize: 9, fill: C.soil, position: "insideBottomRight" }} />}
          </ComposedChart></Chart>}
        {hcd.length > 1 && <Chart titulo="Pressões por posição" h={300}>
          <ComposedChart data={hcd} margin={{ top: 6, right: 10, bottom: 14, left: -12 }}><CartesianGrid stroke="#EEE9DC" /><XAxis dataKey="pos" tick={{ fontSize: 9, fill: C.muted }} /><YAxis tick={{ fontSize: 9, fill: C.muted }} domain={[0, "auto"]} /><Tooltip />
            <Line dataKey="pres" name="Pressão" stroke={C.soil} strokeWidth={1.2} dot={{ r: 1.5, fill: C.soil, strokeWidth: 0 }} connectNulls /></ComposedChart></Chart>}
        {hcd.length > 1 && <Chart titulo="Vazão dos aspersores" h={300}>
          <ComposedChart data={hcd} margin={{ top: 6, right: 10, bottom: 14, left: -12 }}><CartesianGrid stroke="#EEE9DC" /><XAxis dataKey="pos" tick={{ fontSize: 9, fill: C.muted }} /><YAxis tick={{ fontSize: 9, fill: C.muted }} /><Tooltip />
            <Line dataKey="vazao" name="Vazão" stroke={C.water} strokeWidth={1.2} dot={{ r: 1.5, fill: C.water, strokeWidth: 0 }} />
            {hidro && <ReferenceLine y={+hidro.media.toFixed(2)} stroke={C.primary} strokeDasharray="5 4" label={{ value: `média ${hidro.media.toFixed(1)}`, fontSize: 9, fill: C.primary, position: "insideTopRight" }} />}
          </ComposedChart></Chart>}
        {hidro && hidro.ajustado.length > 1 && <Chart titulo="Vazão ajustada (pós-remanejamento)" h={300}>
          <ComposedChart data={hidro.ajustado} margin={{ top: 6, right: 10, bottom: 14, left: -12 }}><CartesianGrid stroke="#EEE9DC" /><XAxis dataKey="novaPos" tick={{ fontSize: 9, fill: C.muted }} /><YAxis tick={{ fontSize: 9, fill: C.muted }} /><Tooltip />
            <Line dataKey="vazao" name="Ajustada" stroke={C.water} strokeWidth={1.3} dot={{ r: 1.5, fill: C.water, strokeWidth: 0 }} /></ComposedChart></Chart>}
        {adeq && <Chart titulo="Adequabilidade — frações da área" h={300} footer={<AdeqAreaLegend />}>
          <ComposedChart data={adeq.curva} margin={{ top: 8, right: 12, bottom: 14, left: -8 }}><CartesianGrid stroke="#EEE9DC" /><XAxis type="number" dataKey="freq" domain={[0, 100]} tick={{ fontSize: 9, fill: C.muted }} /><YAxis tick={{ fontSize: 9, fill: C.muted }} /><Tooltip labelFormatter={(l) => `${l}%`} />
            {cruz && <ReferenceArea x1={0} x2={cruz.freq} fill={C.primary} fillOpacity={0.1} label={{ value: `≥ projeto ${adeq.adq}%`, fontSize: 9, fill: C.primary, position: "insideTop" }} />}
            {cruz && <ReferenceArea x1={cruz.freq} x2={100} fill={C.warn} fillOpacity={0.1} label={{ value: `< projeto ${(100 - adeq.adq).toFixed(1)}%`, fontSize: 9, fill: C.warn, position: "insideTop" }} />}
            <Line dataKey="lamina" name="Lâmina" stroke={C.water} strokeWidth={2} dot={false} />
            <ReferenceLine y={+adeq.lmp.toFixed(2)} stroke={C.primary} strokeDasharray="5 4" label={{ value: `média ${adeq.lmp.toFixed(1)}`, fontSize: 9, fill: C.primary, position: "insideBottomRight" }} />
            {lp != null && <ReferenceLine y={lp} stroke={C.soil} strokeWidth={2} label={{ value: `projeto ${lp}`, fontSize: 9, fill: C.soil, position: "insideTopLeft" }} />}
            {cruz && <ReferenceDot x={cruz.freq} y={cruz.lamina} r={4} fill={C.soil} stroke="#fff" strokeWidth={2} />}
          </ComposedChart></Chart>}
      </div>

      {/* Remanejo dos bocais com vazões ajustadas */}
      {hidro && hidro.mapping.length > 0 && (
        <div style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 14, padding: "12px 14px", marginBottom: 16 }}>
          <h3 style={{ fontFamily: "'Archivo',sans-serif", fontSize: 12.5, textTransform: "uppercase", margin: "0 0 8px" }}>Remanejo dos bocais — vazões ajustadas</h3>
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead><tr><th className="th">Nova pos.</th><th className="th">Vazão ajustada (m³/h)</th><th className="th">Veio da pos.</th><th className="th">Ø (mm)</th></tr></thead>
            <tbody>{[...hidro.mapping].sort((a, b) => a.novaPos - b.novaPos).map((m) => (
              <tr key={m.pos} style={{ borderTop: `1px solid ${C.paper}`, background: m.canhao ? "#FBF3EC" : "#fff" }}>
                <td className="inc" style={{ fontWeight: 700, color: m.canhao ? C.soil : C.primary }}>{m.novaPos}{m.canhao ? " ⚑" : ""}</td>
                <td className="inc" style={{ fontWeight: 600 }}>{m.vazao.toFixed(2)}</td>
                <td className="inc" style={{ color: C.muted }}>{m.pos}</td>
                <td className="inc" style={{ color: C.muted }}>{m.diam ?? "—"}</td>
              </tr>
            ))}</tbody>
          </table>
          <p style={{ fontSize: 10.5, color: C.muted, marginTop: 6 }}>Ordenado pela nova posição (centro → ponta), vazão crescente. ⚑ = canhão hidráulico (fixo na ponta).</p>
        </div>
      )}

      {/* Tabela de controle completa */}
      {ctrl && (
        <div style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 14, padding: "12px 14px", marginBottom: 16 }}>
          <h3 style={{ fontFamily: "'Archivo',sans-serif", fontSize: 12.5, textTransform: "uppercase", margin: "0 0 8px" }}>Tabela de controle do percentímetro (completa)</h3>
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead><tr><th className="th">Perc. %</th><th className="th">Veloc. (m/h)</th><th className="th">Tempo/volta (h)</th><th className="th">Lâmina (mm)</th></tr></thead>
            <tbody>{ctrl.tabela.map((r) => (
              <tr key={r.p} style={{ borderTop: `1px solid ${C.paper}`, background: r.p % 10 === 0 ? "#F0F6F3" : "#fff" }}>
                <td className="inc" style={{ fontWeight: 700, color: C.primary }}>{r.p}</td>
                <td className="inc">{r.vel.toFixed(1)}</td><td className="inc">{r.tv.toFixed(2)}</td><td className="inc" style={{ fontWeight: 600 }}>{r.lam.toFixed(2)}</td>
              </tr>
            ))}</tbody>
          </table>
          <p style={{ fontSize: 10.5, color: C.muted, marginTop: 6 }}>Tabela integral, de 1 em 1% (10% a 100%). Linhas destacadas marcam cada 10%.</p>
        </div>
      )}

      {/* Interpretação */}
      {textos.length > 0 && (
        <div style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 14, padding: "14px 16px", marginBottom: 16 }}>
          <h3 style={{ fontFamily: "'Archivo',sans-serif", fontSize: 12.5, textTransform: "uppercase", margin: "0 0 10px" }}>Interpretação</h3>
          <ul style={{ margin: 0, paddingLeft: 18, display: "flex", flexDirection: "column", gap: 7 }}>{textos.map((t, i) => <li key={i} style={{ fontSize: 13, lineHeight: 1.5 }}>{t}</li>)}</ul>
        </div>
      )}

      {/* Comparação com avaliação anterior na mesma coordenada */}
      {hist && hist.length > 0 && (() => {
        const ant = hist[hist.length - 1];
        const atual = { cuc: unif ? +unif.cuc.toFixed(1) : null, ud: unif ? +unif.ud.toFixed(1) : null, epa: epa != null ? +epa.toFixed(1) : null, adeq: adeq?.adq ?? null };
        const linhas = [["CUC", ant.cuc, atual.cuc, "%"], ["UD", ant.ud, atual.ud, "%"], ["Epa", ant.epa, atual.epa, "%"], ["Adequação", ant.adeq, atual.adeq, "%"]];
        return (
          <div style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 14, padding: "14px 16px", marginBottom: 16 }}>
            <h3 style={{ fontFamily: "'Archivo',sans-serif", fontSize: 12.5, textTransform: "uppercase", margin: "0 0 4px" }}>Comparação com avaliação anterior</h3>
            <p style={{ fontSize: 11.5, color: C.muted, margin: "0 0 10px" }}>Mesma coordenada · anterior de {ant.data}</p>
            <table style={{ width: "100%", borderCollapse: "collapse" }}>
              <thead><tr><th className="th" style={{ textAlign: "left" }}>Índice</th><th className="th">Anterior</th><th className="th">Atual</th><th className="th">Δ</th></tr></thead>
              <tbody>{linhas.map(([nome, a, b, u]) => {
                const d = a != null && b != null ? +(b - a).toFixed(1) : null;
                const cor = d == null ? C.muted : d > 0 ? C.up : d < 0 ? C.warn : C.muted;
                return <tr key={nome} style={{ borderTop: `1px solid ${C.paper}` }}>
                  <td style={{ padding: "7px 2px", fontWeight: 600, fontSize: 12.5 }}>{nome}</td>
                  <td className="inc" style={{ color: C.muted }}>{a == null ? "—" : a + u}</td>
                  <td className="inc" style={{ fontWeight: 700 }}>{b == null ? "—" : b + u}</td>
                  <td className="inc" style={{ color: cor, fontWeight: 700 }}>{d == null ? "—" : (d > 0 ? "▲ " : d < 0 ? "▼ " : "") + Math.abs(d) + u}</td>
                </tr>;
              })}</tbody>
            </table>
          </div>
        );
      })()}
      </div>{/* fim report-area */}

      {/* Fotos do ensaio */}
      <div className="noprint" style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 14, padding: "14px 16px", marginBottom: 12 }}>
        <h3 style={{ fontFamily: "'Archivo',sans-serif", fontSize: 13, margin: "0 0 4px", fontWeight: 700 }}>Fotos do ensaio</h3>
        <p style={{ fontSize: 11.5, color: C.muted, margin: "0 0 10px" }}>Entram no relatório como Anexo A, com data e coordenadas na legenda.</p>
        <label style={{ display: "inline-block", background: C.ink, color: "#fff", padding: "9px 14px", borderRadius: 10, fontSize: 13, fontWeight: 700, fontFamily: "'Archivo',sans-serif", cursor: "pointer" }}>
          + Adicionar fotos
          <input type="file" accept="image/*" multiple onChange={addFotos} style={{ display: "none" }} />
        </label>
        {fotos.length > 0 && (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 8, marginTop: 12 }}>
            {fotos.map((f, i) => (
              <div key={i} style={{ position: "relative", border: `1px solid ${C.line}`, borderRadius: 8, overflow: "hidden" }}>
                <img src={f.url} alt="foto" style={{ width: "100%", height: 80, objectFit: "cover", display: "block" }} />
                <span style={{ position: "absolute", bottom: 0, left: 0, right: 0, background: "rgba(11,61,46,.7)", color: "#fff", fontSize: 9, textAlign: "center" }}>{f.date}</span>
                <button onClick={() => delFoto(i)} style={{ position: "absolute", top: 2, right: 2, border: "none", background: "rgba(0,0,0,.55)", color: "#fff", borderRadius: "50%", width: 20, height: 20, cursor: "pointer", lineHeight: 1 }}>×</button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Salvar avaliação na coordenada */}
      <div className="noprint" style={{ marginBottom: 12 }}>
        <button className="btn" onClick={salvar} style={{ width: "100%", background: C.ink, color: "#fff", padding: 13, fontSize: 14 }}>
          Salvar avaliação nesta coordenada
        </button>
        {msg && <p style={{ textAlign: "center", fontSize: 12, color: C.primary, marginTop: 8, fontWeight: 600 }}>{msg}</p>}
        <p style={{ textAlign: "center", fontSize: 10.5, color: C.muted, marginTop: 6 }}>Fica guardada por coordenada; numa próxima avaliação no mesmo pivô o app recupera e compara.</p>
      </div>

      <div className="noprint" style={{ display: "flex", gap: 8 }}>
        <button className="btn" onClick={imprimir} style={{ flex: 1, background: C.primary, color: "#fff", padding: 14, fontSize: 14, boxShadow: "0 6px 18px rgba(11,61,46,.22)" }}>Imprimir / PDF</button>
        <button className="btn" onClick={baixarHTML} style={{ flex: 1, background: "#fff", color: C.primary, border: `1.5px solid ${C.primary}`, padding: 14, fontSize: 14 }}>Baixar relatório (HTML)</button>
      </div>
      <p className="noprint" style={{ textAlign: "center", fontSize: 10.5, color: C.muted, marginTop: 8 }}>Se a impressão não abrir, use "Baixar relatório (HTML)": abra o arquivo e clique em Imprimir / Salvar em PDF.</p>
      {!unif && !hidro && <p style={{ color: C.muted, fontSize: 13, textAlign: "center", padding: "16px 0" }}>Preencha as seções (ou carregue o exemplo na Capa) para montar o relatório.</p>}
    </div>
  );
}

/* ---------- AUXILIARES ---------- */
function AdeqAreaLegend() {
  const row = (color, text) => (
    <div style={{ display: "flex", alignItems: "flex-start", gap: 8, marginBottom: 5 }}>
      <span style={{ width: 12, height: 12, background: color, opacity: 0.35, border: `1px solid ${color}`, flexShrink: 0, marginTop: 2 }} aria-hidden />
      <span style={{ fontSize: 10.5, color: C.muted, lineHeight: 1.45 }}>{text}</span>
    </div>
  );
  return (
    <div style={{ padding: "4px 10px 10px" }}>
      {row(C.primary, "Área com lâmina igual ou superior à de projeto (adequada).")}
      {row(C.warn, "Área com lâmina inferior à de projeto (déficit).")}
    </div>
  );
}
function Chart({ titulo, children, h, footer }) {
  return (
    <div style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 14, padding: "14px 6px 6px" }}>
      <h3 style={{ fontFamily: "'Archivo',sans-serif", fontSize: 13, margin: "0 0 8px 8px", fontWeight: 700 }}>{titulo}</h3>
      <ResponsiveContainer width="100%" height={h || 220}>{children}</ResponsiveContainer>
      {footer}
    </div>
  );
}
function Big({ t, v, faixa, suf }) {
  const [lbl, cor] = faixa;
  return (
    <div style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 13, padding: "13px 13px 11px" }}>
      <div style={{ fontSize: 11.5, color: C.muted, fontWeight: 600, marginBottom: 4 }}>{t}</div>
      <div style={{ fontFamily: "'Archivo',sans-serif", fontSize: 28, fontWeight: 800, color: cor, lineHeight: 1 }}>{v == null ? "—" : v.toFixed ? v.toFixed(1) : v}<span style={{ fontSize: 14, color: C.muted }}>%</span></div>
      {lbl && <div style={{ fontSize: 10.5, color: cor, fontWeight: 700, marginTop: 5 }}>{lbl}</div>}
    </div>
  );
}
function Small({ t, v, u }) {
  return <div style={{ background: "#F0F6F3", borderRadius: 11, padding: "10px 12px" }}><div style={{ fontSize: 11, color: C.muted, fontWeight: 600 }}>{t}</div><div style={{ fontFamily: "'Archivo',sans-serif", fontSize: 18, fontWeight: 700 }}>{v == null ? "—" : v.toFixed(2)}<span style={{ fontSize: 11, color: C.muted }}> {u}</span></div></div>;
}
function Dark({ t, v, u }) {
  return <div style={{ background: C.ink, borderRadius: 13, padding: "13px 13px 11px", color: "#fff" }}><div style={{ fontSize: 11, opacity: 0.8, fontWeight: 600 }}>{t}</div><div style={{ fontFamily: "'Archivo',sans-serif", fontSize: 25, fontWeight: 800 }}>{v}<span style={{ fontSize: 13, opacity: 0.75 }}> {u}</span></div></div>;
}
function Badge({ l, v, f }) {
  const [txt, cor] = f;
  return <div style={{ display: "flex", alignItems: "center", gap: 6, background: "#F0F6F3", borderRadius: 18, padding: "5px 11px" }}><span style={{ fontSize: 11.5, fontWeight: 700 }}>{l} {v}%</span>{txt && <span style={{ fontSize: 10, fontWeight: 700, color: "#fff", background: cor, borderRadius: 10, padding: "1px 7px" }}>{txt}</span>}</div>;
}
const Vazio = () => <p style={{ color: C.muted, fontSize: 13, textAlign: "center", padding: "26px 0" }}>Sem dados ainda. Carregue o exemplo na Capa ou preencha a seção.</p>;

/* ---------- Figura do pivô central (desenho) ---------- */
function PivotFig() {
  const torres = [122, 210, 298];
  const drops = [78, 100, 144, 166, 188, 232, 254, 276, 320, 342];
  return (
    <svg viewBox="0 0 400 150" width="100%" style={{ display: "block" }} role="img" aria-label="Pivô central">
      {/* céu e sol */}
      <circle cx="352" cy="26" r="13" fill="#F2C14E" opacity="0.9" />
      {[[332,18],[372,16],[362,34]].map(([x,y],i)=>(<line key={i} x1={352} y1={26} x2={x} y2={y} stroke="#F2C14E" strokeWidth="1.5" opacity="0.6" />))}
      {/* solo */}
      <rect x="0" y="120" width="400" height="30" fill="#EFE8D8" />
      <line x1="0" y1="120" x2="400" y2="120" stroke="#C8BFA8" strokeWidth="1.5" />
      {Array.from({ length: 26 }).map((_, i) => (
        <path key={i} d={`M${8 + i * 15} 120 q2 -6 4 0`} stroke="#3F9D6E" strokeWidth="1.6" fill="none" opacity="0.8" />
      ))}
      {/* torre central / ponto de pivô */}
      <rect x="34" y="40" width="6" height="80" rx="2" fill="#0B3D2E" />
      <circle cx="37" cy="38" r="5" fill="#137A63" stroke="#0B3D2E" strokeWidth="1" />
      {/* tubulação lateral */}
      <line x1="37" y1="56" x2="366" y2="56" stroke="#137A63" strokeWidth="4" strokeLinecap="round" />
      {/* treliça */}
      <polyline points={`37,56 ${torres.map((t,i)=>`${(37+(i===0?0:torres[i-1]))/1},48 ${t},56`).join(" ")} 366,56`} fill="none" stroke="#137A63" strokeWidth="1" opacity="0.45" />
      {/* torres móveis */}
      {torres.map((x) => (
        <g key={x}>
          <path d={`M${x - 11} 118 L${x} 56 L${x + 11} 118`} fill="none" stroke="#0B3D2E" strokeWidth="2.4" />
          <line x1={x - 11} y1="118" x2={x + 11} y2="118" stroke="#0B3D2E" strokeWidth="2.4" />
          <circle cx={x} cy="118" r="5.5" fill="#0B3D2E" />
          <circle cx={x} cy="118" r="2" fill="#EFE8D8" />
        </g>
      ))}
      {/* aspersores + borrifo */}
      {drops.map((x, i) => (
        <g key={i}>
          <line x1={x} y1="56" x2={x} y2="66" stroke="#137A63" strokeWidth="1.4" />
          <path d={`M${x} 66 q-7 14 -10 26`} stroke="#2BB3C0" strokeWidth="1.3" fill="none" strokeDasharray="2 3" opacity="0.8" />
          <path d={`M${x} 66 q7 14 10 26`} stroke="#2BB3C0" strokeWidth="1.3" fill="none" strokeDasharray="2 3" opacity="0.8" />
          <circle cx={x} cy="70" r="1.4" fill="#2BB3C0" />
        </g>
      ))}
      {/* canhão hidráulico na ponta */}
      <line x1="366" y1="56" x2="380" y2="46" stroke="#0B3D2E" strokeWidth="3" strokeLinecap="round" />
      <path d="M380 46 Q394 40 399 78" stroke="#2BB3C0" strokeWidth="2" fill="none" strokeDasharray="3 4" />
      <path d="M380 46 Q392 48 396 64" stroke="#2BB3C0" strokeWidth="1.4" fill="none" strokeDasharray="2 4" opacity="0.7" />
    </svg>
  );
}
